const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'live-bind-'));
  const esmPath = path.join(dir, 'counter.mjs');
  const cjsPath = path.join(dir, 'counter.cjs');

  fs.writeFileSync(
    esmPath,
    'export let count = 0;\nexport function bump() { count += 1; }\n'
  );
  fs.writeFileSync(
    cjsPath,
    'let count = 0;\nfunction bump() { count += 1; }\nmodule.exports = { count, bump };\n'
  );

  const esm = await import('file://' + esmPath);
  esm.bump();
  console.log('esm.count after bump: ' + esm.count);

  const cjs = require(cjsPath);
  cjs.bump();
  console.log('cjs.count after bump: ' + cjs.count);

  fs.rmSync(dir, { recursive: true, force: true });
})();

