function canDropUnused(moduleSrc, consumerSrc, unusedName) {
  const opaqueObjectExport =
    /module\.exports\s*=/.test(moduleSrc) || /export\s+default\s*\{/.test(moduleSrc);
  if (opaqueObjectExport) return false; // bundler can't statically see inside

  const namedExport = new RegExp(
    'export\\s+(function|const|let|class)\\s+' + unusedName + '\\b'
  ).test(moduleSrc);
  const staticNamedImport = /import\s*\{[^}]*\}\s*from/.test(consumerSrc);
  const importsUnused = new RegExp(
    'import\\s*\\{[^}]*\\b' + unusedName + '\\b[^}]*\\}'
  ).test(consumerSrc);
  return namedExport && staticNamedImport && !importsUnused;
}

const objectModule =
  'function add(a, b) { return a + b; }\n' +
  'function mul(a, b) { return a * b; }\n' +
  'module.exports = { add, mul };\n';
const objectConsumer = "const { add } = require('./u');\nconsole.log(add(2, 3));\n";

const namedModule =
  'export function add(a, b) { return a + b; }\n' +
  'export function mul(a, b) { return a * b; }\n';
const namedConsumer = "import { add } from './u.js';\nconsole.log(add(2, 3));\n";

console.log("object-export shape:  can drop unused 'mul'? " + canDropUnused(objectModule, objectConsumer, 'mul'));
console.log("named-export shape:   can drop unused 'mul'? " + canDropUnused(namedModule, namedConsumer, 'mul'));

