exercises.prompt:
Generators are lazy — nothing executes until `.next()` is called. Implement an infinite Fibonacci generator plus a `take(gen, n)` helper that collects the first `n` values without ever materializing the infinite sequence.

Example:
```js
console.log(JSON.stringify(take(fibonacci(), 8)));
console.log(JSON.stringify(take(fibonacci(), 1)));
console.log(JSON.stringify(fibonacci().next()));
```
Expected output:
```
[0,1,1,2,3,5,8,13]
[0]
{"value":0,"done":false}
```

exercises.solution:
function* fibonacci() {
  let [a, b] = [0, 1];
  while (true) {
    yield a;
    [a, b] = [b, a + b];
  }
}

function take(gen, n) {
  const out = [];
  for (const value of gen) {
    if (out.length >= n) break;
    out.push(value);
  }
  return out;
}

console.log(JSON.stringify(take(fibonacci(), 8)));
console.log(JSON.stringify(take(fibonacci(), 1)));
console.log(JSON.stringify(fibonacci().next()));

