exercises.prompt:
Write `setIn(obj, path, value)` — it returns a NEW object/array with the value at `path` (an array of keys/indices) replaced, without mutating the original. Objects/arrays along the path are shallow-copied; every branch NOT on the path must keep reference identity (`===`). Handle both object keys and array indices.

Example:
```js
const state = {
  user: { name: 'Ada', prefs: { theme: 'dark', lang: 'en' } },
  items: [1, 2, 3],
};

const next = setIn(state, ['user', 'prefs', 'theme'], 'light');
console.log('theme updated:', next.user.prefs.theme);
console.log('original untouched:', state.user.prefs.theme === 'dark');
console.log('ancestors recreated:', next.user !== state.user && next.user.prefs !== state.user.prefs);
console.log('untouched branch shared:', next.items === state.items);

const next2 = setIn(state, ['items', 1], 99);
console.log('array updated:', JSON.stringify(next2.items));
console.log('original array untouched:', JSON.stringify(state.items) === '[1,2,3]');
```
Expected output:
```
theme updated: light
original untouched: true
ancestors recreated: true
untouched branch shared: true
array updated: [1,99,3]
original array untouched: true
```

exercises.solution:
function setIn(obj, path, value) {
  if (path.length === 0) return value;
  const [key, ...rest] = path;
  const base = obj == null ? (typeof key === 'number' ? [] : {}) : obj;
  const clone = Array.isArray(base) ? base.slice() : { ...base };
  clone[key] = setIn(base[key], rest, value);
  return clone;
}

const state = {
  user: { name: 'Ada', prefs: { theme: 'dark', lang: 'en' } },
  items: [1, 2, 3],
};

const next = setIn(state, ['user', 'prefs', 'theme'], 'light');
console.log('theme updated:', next.user.prefs.theme);
console.log('original untouched:', state.user.prefs.theme === 'dark');
console.log('ancestors recreated:', next.user !== state.user && next.user.prefs !== state.user.prefs);
console.log('untouched branch shared:', next.items === state.items);

const next2 = setIn(state, ['items', 1], 99);
console.log('array updated:', JSON.stringify(next2.items));
console.log('original array untouched:', JSON.stringify(state.items) === '[1,2,3]');

